package io.github.deepseekbridge;
import android.app.Application;import android.content.Context;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import javax.crypto.spec.SecretKeySpec;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,33},manifest=Config.NONE,application=Application.class)
public class ExtensionHubTest {
 Context context;ExtensionHub hub;LocalState vault;final List<JSONObject> events=new CopyOnWriteArrayList<>();
 @Before public void setup()throws Exception {context=RuntimeEnvironment.getApplication();vault=new LocalState(new EncryptedStateStore(new File(context.getCacheDir(),"extensions-"+UUID.randomUUID()+".enc"),new SecretKeySpec(new byte[32],"AES")));hub=new ExtensionHub(context,vault,(project,config)->{throw new IOException("No fixture child configured");},events::add);}
 @After public void cleanup(){hub.close();}
 @Test public void pluginZipImportsDisabledSkillsAndMcpThenCanBeEnabledAndRemoved()throws Exception {File zip=new File(context.getCacheDir(),"plugin-"+UUID.randomUUID()+".zip");try(java.util.zip.ZipOutputStream out=new java.util.zip.ZipOutputStream(new FileOutputStream(zip))){for(String[] item:new String[][]{{".claude-plugin/plugin.json","{\"name\":\"Fixture plugin\",\"version\":\"1.0\"}"},{".mcp.json","{\"mcpServers\":{\"fixture\":{\"command\":\"python3\",\"args\":[\"${CLAUDE_PLUGIN_ROOT}/server.py\"]}}}"},{"skills/review/SKILL.md","# Fixture skill\nInspect project files."},{"server.py","print('fixture')"}}){out.putNextEntry(new java.util.zip.ZipEntry(item[0]));out.write(item[1].getBytes(StandardCharsets.UTF_8));out.closeEntry();}}JSONObject imported=hub.install(android.net.Uri.fromFile(zip));JSONObject plugin=imported.getJSONArray("plugins").getJSONObject(0);String id=plugin.getString("id");assertFalse(plugin.getBoolean("enabled"));assertFalse(imported.getJSONArray("servers").getJSONObject(0).getBoolean("enabled"));assertTrue(imported.getJSONArray("servers").getJSONObject(0).getJSONArray("args").getString(0).startsWith("/studio-plugins/"+id));hub.pluginToggle(id,true);assertTrue(hub.skill(id,"skills/review/SKILL.md").getString("content").contains("Fixture skill"));try{hub.skill(id,"../../secret/SKILL.md");fail();}catch(IOException expected){}assertEquals(0,hub.pluginRemove(id).getJSONArray("plugins").length());assertFalse(new File(hub.directory,id).exists());}
 @Test public void pluginTraversalCannotWriteOutsideItsNewManagedDirectory()throws Exception {File zip=new File(context.getCacheDir(),"bad-plugin-"+UUID.randomUUID()+".zip");String name="escape-"+UUID.randomUUID();try(java.util.zip.ZipOutputStream out=new java.util.zip.ZipOutputStream(new FileOutputStream(zip))){out.putNextEntry(new java.util.zip.ZipEntry("../"+name));out.write("must not escape".getBytes(StandardCharsets.UTF_8));out.closeEntry();}try{hub.install(android.net.Uri.fromFile(zip));fail();}catch(IOException expected){}assertFalse(new File(hub.directory,name).exists());assertEquals(0,hub.snapshot().getJSONArray("plugins").length());}
 @Test public void configAndSecretsAreEncryptedAndNeverIncludedInWorkerSnapshots()throws Exception {hub.upsert(new JSONObject().put("id","fixture").put("name","MCP").put("type","http").put("url","https://example.test/mcp").put("enabled",true).put("headers",new JSONObject().put("Authorization","Bearer fixture-private-secret")));assertTrue(vault.load().contains("fixture-private-secret"));assertFalse(hub.snapshot().toString().contains("fixture-private-secret"));assertFalse(hub.snapshot().getJSONArray("servers").getJSONObject(0).has("headers"));assertTrue(hub.snapshot().getJSONArray("servers").getJSONObject(0).getBoolean("hasSecret"));hub.upsert(new JSONObject().put("id","fixture").put("name","Renamed").put("type","http").put("url","https://example.test/mcp").put("enabled",true));assertEquals("Bearer fixture-private-secret",hub.server("fixture").getJSONObject("headers").getString("Authorization"));hub.toggle("fixture",false,false);try{hub.server("fixture");fail();}catch(IOException expected){} }
 @Test public void transportRejectsProtocolEscapesRedirectDestinationsAndHeaderInjection()throws Exception {JSONObject s=ExtensionHub.normalize(new JSONObject().put("id","fixture").put("type","http").put("url","https://example.test/mcp"));assertEquals("https://example.test/mcp?cursor=2",ExtensionHub.checkedUrl(s,"https://example.test/mcp?cursor=2").toString());for(String raw:new String[]{"https://other.test/mcp","http://example.test/mcp","https://example.test/elsewhere","https://user:pass@example.test/mcp","file:///data/private"})try{ExtensionHub.checkedUrl(s,raw);fail(raw);}catch(Exception expected){}for(String raw:new String[]{"javascript:alert(1)","https://bridge.local/engine.html","https://user:pass@example.test/mcp"})try{ExtensionHub.normalize(new JSONObject().put("type","http").put("url",raw));fail(raw);}catch(Exception expected){}try{ExtensionHub.normalize(new JSONObject().put("type","http").put("url","https://example.test/mcp").put("headers",new JSONObject().put("Authorization","x\r\nInjected: true")));fail();}catch(IOException expected){} }
 @Test public void nativeHttpStreamsActualServerBytesAndNeverFollowsRedirects()throws Exception {try(ServerSocket server=new ServerSocket(0,4,InetAddress.getByName("127.0.0.1"))){AtomicReference<String> request=new AtomicReference<>();Thread responder=new Thread(()->{try(Socket socket=server.accept()){BufferedReader in=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.UTF_8));StringBuilder headers=new StringBuilder();String line;while((line=in.readLine())!=null&&!line.isEmpty())headers.append(line).append('\n');request.set(headers.toString());byte[] body="data: {\"jsonrpc\":\"2.0\",\"result\":\"中文\"}\n\n".getBytes(StandardCharsets.UTF_8);OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(body);out.flush();}catch(Exception ignored){}});responder.setDaemon(true);responder.start();String url="http://127.0.0.1:"+server.getLocalPort()+"/mcp";hub.upsert(new JSONObject().put("id","native-http").put("type","http").put("url",url).put("enabled",true).put("headers",new JSONObject().put("Authorization","Bearer fixture-key")));hub.http("request",new JSONObject().put("server","native-http").put("url",url).put("method","POST").put("body","{}").put("headers",new JSONObject().put("Content-Type","application/json").put("Mcp-Method","tools/list")));long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(events.stream().noneMatch(e->e.optString("event").equals("end"))&&System.nanoTime()<end)Thread.sleep(10);assertTrue(request.get().contains("Bearer fixture-key"));assertTrue(events.stream().anyMatch(e->e.optString("event").equals("data")&&e.optString("data").contains("中文")));assertTrue(events.stream().anyMatch(e->e.optString("event").equals("end")));assertFalse(events.toString().contains("fixture-key"));}}
 @Test public void nativeStdioKeepsSeparatePipesAndStopsWhenServerIsDisabled()throws Exception {hub.close();PipedInputStream stdout=new PipedInputStream();PipedOutputStream response=new PipedOutputStream(stdout);ByteArrayOutputStream stdin=new ByteArrayOutputStream();AtomicBoolean stopped=new AtomicBoolean();CountDownLatch exit=new CountDownLatch(1);ExtensionHub.Child child=new ExtensionHub.Child(){public InputStream stdout(){return stdout;}public InputStream stderr(){return new ByteArrayInputStream(new byte[0]);}public OutputStream stdin(){return stdin;}public int await()throws Exception{exit.await(5,TimeUnit.SECONDS);return 0;}public void stop(){stopped.set(true);exit.countDown();try{response.close();}catch(Exception ignored){}}};hub=new ExtensionHub(context,vault,(project,config)->child,events::add);hub.upsert(new JSONObject().put("id","local").put("type","stdio").put("command","node").put("args",new JSONArray().put("/workspace/mcp.mjs")).put("enabled",true));String id=hub.open("project","local").getString("id");hub.write(id,"{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/list\"}");assertTrue(new String(stdin.toByteArray(),StandardCharsets.UTF_8).endsWith("\n"));response.write("{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{\"tools\":[]}}\n".getBytes(StandardCharsets.UTF_8));response.flush();long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(events.isEmpty()&&System.nanoTime()<end)Thread.sleep(10);assertTrue(events.stream().anyMatch(e->e.optString("event").equals("message")));hub.toggle("local",false,false);assertTrue(stopped.get());}
}
